CREATE TABLE IF NOT EXISTS otp(id TEXT PRIMARY KEY, code_hash TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY, created_at INTEGER NOT NULL, stepup_at INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY, title TEXT NOT NULL, area TEXT, kind TEXT NOT NULL DEFAULT 'fleet', state TEXT NOT NULL DEFAULT 'open', snooze_until INTEGER, why TEXT, if_wait TEXT, url TEXT, identity INTEGER NOT NULL DEFAULT 0, fix_cmd TEXT, source TEXT, priority INTEGER NOT NULL DEFAULT 5, updated_at INTEGER);
CREATE TABLE IF NOT EXISTS fleet_queue(id INTEGER PRIMARY KEY AUTOINCREMENT, task_id TEXT NOT NULL, status TEXT NOT NULL, queued_at INTEGER NOT NULL, done_at INTEGER, result TEXT);
CREATE TABLE IF NOT EXISTS checks(name TEXT PRIMARY KEY, ok INTEGER NOT NULL, detail TEXT, at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER NOT NULL, cmd TEXT NOT NULL, ok INTEGER NOT NULL, result TEXT, undo TEXT, undone INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS notifications(key TEXT PRIMARY KEY, at INTEGER NOT NULL, subject TEXT, sent INTEGER NOT NULL DEFAULT 0, error TEXT);
